// ../public/lab/score.js
function qualityScore(q) {
  if (!q) return null;
  const hidden = q.hiddenTotal ? q.hiddenPass / q.hiddenTotal : 0;
  const floor = [q.build, q.typecheck, q.ownTests].filter(Boolean).length / 3;
  const base = 60 * hidden + 20 * floor;
  const s2 = typeof q.judgeScore === "number" ? base + 2 * q.judgeScore : base * 100 / 80;
  return Math.round(s2 * 10) / 10;
}
__name(qualityScore, "qualityScore");

